#region

using System.Globalization;
using System.Text;
using CS2SchemaGen.Diagnostics;
using CS2SchemaGen.Models;

#endregion

namespace CS2SchemaGen.Emitters;

internal static class ModuleEmitter
{
    // ── Source builders ──────────────────────────────────────────────────────────

    // Standard preamble for every SDK file. Emits:
    //   • `// <auto-generated/>` — IDE/formatter signal + stale-file-cleanup discriminator
    //   • SDK header (file-relative path, regen instructions, "do not edit" notice)
    //   • Schema-revision stamp (silent on test fixtures with no revision metadata)
    //
    // `relativePath` is the SDK-root-relative path without `.cs`, e.g. "Client/CCSPlayer"
    // or "Attributes". `namespaceLabel` is the root namespace ("CS2OpenSchema").
    internal static void AppendSdkHeader(
        StringBuilder sb,
        string namespaceLabel,
        string relativePath,
        SchemaRoot schema)
    {
        sb.AppendLine("// <auto-generated/>");
        sb.Append("// ").Append(namespaceLabel).Append(" — ").AppendLine(relativePath);
        sb.AppendLine("// Generated from upstream cs2_schema.json. Regenerate with cs2-sdk-exporter.");
        sb.AppendLine("// Do not edit this file directly.");
        sb.AppendLine();

        int posBeforeStamp = sb.Length;
        AppendSchemaStamp(sb, schema);
        if (sb.Length > posBeforeStamp)
        {
            sb.AppendLine();
        }
    }

    // ME-3 / F3: when schemas.json carries top-level `revision`, `version_date`, or
    // `version_time` (the DumpSource2 dump always does), emit a single-line stamp
    // so consumers can trace generated code back to a dump. Stays silent for
    // hand-written test fixtures that omit the fields. Internal so SyntheticTypes
    // can share the same format.
    internal static void AppendSchemaStamp(StringBuilder sb, SchemaRoot schema)
    {
        if (!schema.Revision.HasValue && schema.VersionDate is null && schema.VersionTime is null)
        {
            return;
        }

        sb.Append("// Schema revision: ");
        if (schema.Revision.HasValue)
        {
            sb.Append(schema.Revision.Value.ToString(CultureInfo.InvariantCulture));
        }
        else
        {
            sb.Append("(unknown)");
        }

        // The two fields do not compose the same way in both formats. 1.x split
        // them ("May 21 2026" + "17:11:59"), so both were needed. 2.0's
        // `version_time` is a full ISO 8601 instant ("2026-08-03T18:18:10Z")
        // that already contains `version_date`, and concatenating gave
        // "2026-08-03 2026-08-03T18:18:10Z" in the header of every emitted file.
        // A 'T' separator is what distinguishes a whole timestamp from a
        // time-of-day, so prefer it alone when present.
        bool timeIsFullInstant = schema.VersionTime is not null
            && schema.VersionTime.Contains('T', StringComparison.Ordinal);

        if (schema.VersionDate is not null && !timeIsFullInstant)
        {
            sb.Append(" — ");
            sb.Append(schema.VersionDate);
        }

        if (schema.VersionTime is not null)
        {
            sb.Append(timeIsFullInstant ? " — " : " ");
            sb.Append(schema.VersionTime);
        }

        sb.AppendLine();
    }

    internal static void EmitAll(IGeneratorSink sink, SchemaRoot schema, string ns)
    {
        // ── Step 0: build C++ → C# name map and give it to TypeMapper ───────────
        //
        // This ensures all type references (field types, parents) use the same name
        // as their declaration, including flag-aware suffix renaming.
        //
        // Collision rule: if two distinct C++ names map to the same C# name (e.g.
        // `CHintMessage` and `CHintMessageQueue` both become `CHintMessage` after
        // CA1711 suffix-strip), the second occurrence falls back to the sanitized
        // raw C++ name (`CHintMessageQueue`). Stable, order-independent through
        // the schema's natural ordering, and avoids duplicate class declarations
        // in the same module.

        Dictionary<string, string> cppToCsName = new(StringComparer.Ordinal);
        HashSet<string> usedCsNames = new(StringComparer.Ordinal);

        string DisambiguateCsName(string cppName, string desired)
        {
            if (usedCsNames.Add(desired))
            {
                return desired;
            }

            string fallback = NameHelpers.SanitizeName(cppName);
            if (usedCsNames.Add(fallback))
            {
                return fallback;
            }

            int n = 2;
            string disambiguated = fallback + n;
            while (!usedCsNames.Add(disambiguated))
            {
                n++;
                disambiguated = fallback + n;
            }

            return disambiguated;
        }

        // Two-pass so the "natural" mapping always wins the un-suffixed name:
        //   pass 1 — entries where the desired C# name equals the sanitized C++ name
        //            (no rename happened). These reserve their spelling first.
        //   pass 2 — entries that came from a transformation (CA1711 strip, _t/_s
        //            removal, etc.) get their desired name if it's still free, else
        //            fall back to the sanitized original via DisambiguateCsName.
        // Without this split, schema declaration order determines which class wins
        // the un-suffixed name — a `CHintMessageQueue` listed before `CHintMessage`
        // would steal `CHintMessage` and force the natural one to `CHintMessage2`.

        List<(string cpp, string desired)> deferred = new();

        void Register(string cppName, string desired)
        {
            if (cppToCsName.ContainsKey(cppName))
            {
                return;
            }

            if (desired == NameHelpers.SanitizeName(cppName))
            {
                cppToCsName[cppName] = DisambiguateCsName(cppName, desired);
            }
            else
            {
                deferred.Add((cppName, desired));
            }
        }

        foreach (ClassModel cls in schema.Classes)
        {
            Register(cls.Name, NameHelpers.ToTypeName(cls.Name, false));
        }

        foreach (EnumModel en in schema.Enums)
        {
            Register(en.Name, NameHelpers.ToTypeName(en.Name, true, en.IsFlags));
        }

        // Synthetic types are handled inside TypeMapper.MapAtomic via ToTypeName directly,
        // but add them here so DeclaredClassType references also resolve correctly.
        foreach (string synth in TypeMapper.SyntheticAtoms)
        {
            Register(synth, NameHelpers.ToTypeName(synth));
        }

        foreach ((string cpp, string desired) in deferred)
        {
            if (!cppToCsName.ContainsKey(cpp))
            {
                cppToCsName[cpp] = DisambiguateCsName(cpp, desired);
            }
        }

        TypeMapper.SetNameMap(cppToCsName);
        TypeMapper.BeginEmission();

        // ── Step 1: group every class/enum by name ───────────────────────────────

        Dictionary<string, List<ClassModel>> classGroups = new(StringComparer.Ordinal);
        foreach (ClassModel cls in schema.Classes)
        {
            if (!classGroups.TryGetValue(cls.Name, out List<ClassModel>? list))
            {
                classGroups[cls.Name] = list = [];
            }

            list.Add(cls);
        }

        Dictionary<string, List<EnumModel>> enumGroups = new(StringComparer.Ordinal);
        foreach (EnumModel en in schema.Enums)
        {
            if (!enumGroups.TryGetValue(en.Name, out List<EnumModel>? list))
            {
                enumGroups[en.Name] = list = [];
            }

            list.Add(en);
        }

        // ── Step 2: initial classification ───────────────────────────────────────
        //
        //  Full duplicate  = same name, multiple modules, identical fingerprint
        //                    → emit one copy to CS2Schema.Shared
        //  Genuine conflict = same name, multiple modules, different fingerprint
        //                    → each module keeps its own copy
        //  Unique           = appears in exactly one module
        //                    → per-module (CS2Schema.{Module})

        List<ClassModel> sharedClasses = [];
        List<EnumModel> sharedEnums = [];
        Dictionary<string, List<ClassModel>> moduleClasses = new(StringComparer.Ordinal);
        Dictionary<string, List<EnumModel>> moduleEnums = new(StringComparer.Ordinal);

        foreach (KeyValuePair<string, List<ClassModel>> kvp in classGroups)
        {
            List<ClassModel> list = kvp.Value;
            if (list.Count == 1)
            {
                AddToModule(moduleClasses, list[0].Module, list[0]);
            }
            else if (AllClassesIdentical(list))
            {
                sharedClasses.Add(list[0]);
            }
            else
            {
                HashSet<string> seenModules = new(StringComparer.Ordinal);
                foreach (ClassModel cls in list)
                {
                    if (seenModules.Add(cls.Module))
                    {
                        AddToModule(moduleClasses, cls.Module, cls);
                    }
                }
            }
        }

        foreach (KeyValuePair<string, List<EnumModel>> kvp in enumGroups)
        {
            List<EnumModel> list = kvp.Value;
            if (list.Count == 1)
            {
                AddToModule(moduleEnums, list[0].Module, list[0]);
            }
            else if (AllEnumsIdentical(list))
            {
                sharedEnums.Add(list[0]);
            }
            else
            {
                HashSet<string> seenModules = new(StringComparer.Ordinal);
                foreach (EnumModel en in list)
                {
                    if (seenModules.Add(en.Module))
                    {
                        AddToModule(moduleEnums, en.Module, en);
                    }
                }
            }
        }

        // ── Step 3: conflict propagation ─────────────────────────────────────────
        //
        // The shared file can only safely import the root namespace and namespaces of
        // modules that are not involved in genuine naming conflicts.  For CS2 that
        // means the shared file cannot have `using CS2Schema.Client;` or
        // `using CS2Schema.Server;`, because those two modules share 97+ names.
        //
        // This also means the shared file cannot reference any type that lives
        // exclusively inside a conflicting module — whether that type itself is a
        // genuine conflict or just happens to be unique to client/server.
        //
        // Algorithm:
        //  1. Determine which modules participate in genuine conflicts.
        //  2. Seed ambiguousNames with every name currently in those module buckets
        //     (they are inaccessible from the shared file).
        //  3. Propagate: if a shared class references an ambiguous name (in parents or
        //     field types), reclassify it to per-module, add its name to ambiguousNames,
        //     and repeat until stable.
        //
        // Enums are not propagated (no parents, no typed field references).

        // 3a. Which modules have genuine inter-module name conflicts?
        HashSet<string> conflictingModuleNames = new(StringComparer.Ordinal);
        foreach (KeyValuePair<string, List<ClassModel>> kvp in classGroups)
        {
            if (kvp.Value.Count > 1 && !AllClassesIdentical(kvp.Value))
            {
                foreach (ClassModel cls in kvp.Value)
                {
                    conflictingModuleNames.Add(cls.Module);
                }
            }
        }

        foreach (KeyValuePair<string, List<EnumModel>> kvp in enumGroups)
        {
            if (kvp.Value.Count > 1 && !AllEnumsIdentical(kvp.Value))
            {
                foreach (EnumModel en in kvp.Value)
                {
                    conflictingModuleNames.Add(en.Module);
                }
            }
        }

        // 3b. Seed: every name already in a conflicting-module bucket is inaccessible.
        HashSet<string> ambiguousNames = new(StringComparer.Ordinal);
        foreach (string module in conflictingModuleNames)
        {
            if (moduleClasses.TryGetValue(module, out List<ClassModel>? mCls))
            {
                foreach (ClassModel cls in mCls)
                {
                    ambiguousNames.Add(NameHelpers.SanitizeName(cls.Name));
                }
            }

            if (moduleEnums.TryGetValue(module, out List<EnumModel>? mEnm))
            {
                foreach (EnumModel en in mEnm)
                {
                    ambiguousNames.Add(NameHelpers.SanitizeName(en.Name));
                }
            }
        }

        // 3c. Propagate through shared classes.
        bool changed = true;
        while (changed)
        {
            changed = false;
            for (int i = sharedClasses.Count - 1; i >= 0; i--)
            {
                ClassModel cls = sharedClasses[i];
                if (ClassReferencesAmbiguous(cls, ambiguousNames))
                {
                    sharedClasses.RemoveAt(i);
                    ambiguousNames.Add(NameHelpers.SanitizeName(cls.Name));
                    HashSet<string> seenM = new(StringComparer.Ordinal);
                    foreach (ClassModel c in classGroups[cls.Name])
                    {
                        if (seenM.Add(c.Module))
                        {
                            AddToModule(moduleClasses, c.Module, c);
                        }
                    }

                    changed = true;
                }
            }
        }

        // ── Step 4: build name sets for SyntheticTypes and stubs ─────────────────

        HashSet<string> reflectedNames = new(StringComparer.Ordinal);
        foreach (ClassModel cls in sharedClasses)
        {
            reflectedNames.Add(NameHelpers.SanitizeName(cls.Name));
        }

        foreach (KeyValuePair<string, List<ClassModel>> kvp in moduleClasses)
        foreach (ClassModel cls in kvp.Value)
        {
            reflectedNames.Add(NameHelpers.SanitizeName(cls.Name));
        }

        HashSet<string> allDefinedNames = new(reflectedNames, StringComparer.Ordinal);
        foreach (EnumModel en in sharedEnums)
        {
            allDefinedNames.Add(NameHelpers.SanitizeName(en.Name));
        }

        foreach (KeyValuePair<string, List<EnumModel>> kvp in moduleEnums)
        foreach (EnumModel en in kvp.Value)
        {
            allDefinedNames.Add(NameHelpers.SanitizeName(en.Name));
        }

        foreach (string s in TypeMapper.SyntheticAtoms)
        {
            allDefinedNames.Add(s);
        }

        // ── Step 5: collect forward-declared stubs ────────────────────────────────
        //
        // Keys are sanitized C# names (used for stub-class identifiers and dedup
        // against allDefinedNames). Values are the original C++ names — CE-1 uses
        // these to emit [NativeName] on stubs whose sanitized name differs from
        // their source (e.g. "Outer::Inner::Foo" → "Outer_Inner_Foo").

        Dictionary<string, string> referencedNames = new(StringComparer.Ordinal);
        foreach (ClassModel cls in sharedClasses)
        {
            CollectFromClass(cls, referencedNames);
        }

        foreach (KeyValuePair<string, List<ClassModel>> kvp in moduleClasses)
        foreach (ClassModel cls in kvp.Value)
        {
            CollectFromClass(cls, referencedNames);
        }

        SortedDictionary<string, string> stubNames = new(StringComparer.Ordinal);
        foreach (KeyValuePair<string, string> kv in referencedNames)
        {
            if (!allDefinedNames.Contains(kv.Key))
            {
                stubNames[kv.Key] = kv.Value;
            }
        }

        // ── Step 6: namespace map for minimal per-file using directives ─────────────
        //
        // Build a sanitized-name → namespace map covering every type that will exist.
        // BuildModuleSource uses this to import only the namespaces it actually needs,
        // so each generated file has a tight, readable using-directive list.

        SortedSet<string> allModules = new(moduleClasses.Keys, StringComparer.Ordinal);
        foreach (string k in moduleEnums.Keys)
        {
            allModules.Add(k);
        }

        string sharedNs = ns + "." + ToNamespacePart("shared"); // "Common" — avoids VB keyword "Shared"

        // Multi-valued: a "genuine conflict" type (same name, different fingerprint
        // in two modules) lives in both module buckets, so it has two namespaces.
        // BuildModuleSource resolves references with a "prefer self" rule — if the
        // file's own namespace is a candidate, no using directive is needed at all
        // (namespace nesting picks up same-namespace types). Without this, a single
        // last-write-wins entry would point Client files at Server (and vice-versa)
        // for every conflicting name, producing a wave of dead usings that the
        // formatter has to strip on every regen.
        Dictionary<string, HashSet<string>> nameToNs = new(StringComparer.Ordinal);

        void RecordNs(string sanitizedName, string targetNs)
        {
            if (!nameToNs.TryGetValue(sanitizedName, out HashSet<string>? set))
            {
                nameToNs[sanitizedName] = set = new HashSet<string>(StringComparer.Ordinal);
            }

            set.Add(targetNs);
        }

        // Synthetics live in the root namespace
        foreach (string s in TypeMapper.SyntheticAtoms)
        {
            RecordNs(s, ns);
        }

        // Shared types
        foreach (ClassModel cls in sharedClasses)
        {
            RecordNs(NameHelpers.SanitizeName(cls.Name), sharedNs);
        }

        foreach (EnumModel en in sharedEnums)
        {
            RecordNs(NameHelpers.SanitizeName(en.Name), sharedNs);
        }

        // Per-module types
        foreach (KeyValuePair<string, List<ClassModel>> kvp in moduleClasses)
        {
            string moduleNs2 = ns + "." + ToNamespacePart(kvp.Key);
            foreach (ClassModel cls in kvp.Value)
            {
                RecordNs(NameHelpers.SanitizeName(cls.Name), moduleNs2);
            }
        }

        foreach (KeyValuePair<string, List<EnumModel>> kvp in moduleEnums)
        {
            string moduleNs2 = ns + "." + ToNamespacePart(kvp.Key);
            foreach (EnumModel en in kvp.Value)
            {
                RecordNs(NameHelpers.SanitizeName(en.Name), moduleNs2);
            }
        }
        // Stubs are in the root namespace; they are not in nameToNs because they are
        // referenced-but-undefined types. If a reference lookup misses, root ns is assumed.

        // ── Step 7: emit per-type files ───────────────────────────────────────────
        //
        // One reflected class or enum per source file. The "CS2Schema." prefix on
        // every AddSource hint is a filesystem-only name that the Exporter parses
        // with ExporterCore.DeriveOutputName. It is not affected by the
        // CS2SchemaGen_Namespace MSBuild override — the namespace inside the file
        // uses `ns` (the property's value), but the on-disk hint stays constant so
        // the Exporter's prefix-strip stays a simple constant.
        //
        // Hint name shape: `CS2Schema.{module}.{typeName}.g.cs`. The Exporter
        // splits on the inner `.` to derive `{Module}/{TypeName}.cs` on disk.
        //
        // Case-collision defense: filenames sharing a path (same module) and
        // differing only in case would collide on case-insensitive filesystems
        // (macOS APFS, Windows NTFS). We track `{module}/{typename-lower}` and
        // fall back to appending a digit suffix on collision so the regen never
        // silently overwrites one file with another's content.

        HashSet<string> usedFilePaths = new(StringComparer.OrdinalIgnoreCase);

        void EmitTypeFile(string moduleHint, string moduleNamespace, ClassModel? cls, EnumModel? en)
        {
            string typeFile = cls is not null
                ? NameHelpers.SanitizeFilename(NameHelpers.Esc(TypeMapper.LookupCsName(cls.Name)))
                : NameHelpers.SanitizeFilename(NameHelpers.Esc(TypeMapper.LookupCsName(en!.Name, true, en.IsFlags)));

            string moduleDir = ToNamespacePart(moduleHint);
            string relativePath = $"{moduleDir}/{typeFile}";
            if (!usedFilePaths.Add(relativePath))
            {
                int n = 2;
                while (!usedFilePaths.Add(relativePath + n))
                {
                    n++;
                }

                typeFile += n;
                relativePath = $"{moduleDir}/{typeFile}";
            }

            string source = cls is not null
                ? BuildModuleSource(relativePath, moduleNamespace, [cls], null, ns, nameToNs, schema)
                : BuildModuleSource(relativePath, moduleNamespace, null, [en!], ns, nameToNs, schema);

            sink.AddSource(relativePath, source);
        }

        foreach (string module in allModules)
        {
            moduleClasses.TryGetValue(module, out List<ClassModel>? mClasses);
            moduleEnums.TryGetValue(module, out List<EnumModel>? mEnums);
            string moduleNs = ns + "." + ToNamespacePart(module);
            string moduleFile = NameHelpers.SanitizeFilename(module);

            if (mClasses != null)
            {
                foreach (ClassModel cls in mClasses)
                {
                    EmitTypeFile(moduleFile, moduleNs, cls, null);
                }
            }

            if (mEnums != null)
            {
                foreach (EnumModel en in mEnums)
                {
                    EmitTypeFile(moduleFile, moduleNs, null, en);
                }
            }
        }

        // ── Step 8: emit shared types (one file each) ─────────────────────────────

        foreach (ClassModel cls in sharedClasses)
        {
            EmitTypeFile("shared", sharedNs, cls, null);
        }

        foreach (EnumModel en in sharedEnums)
        {
            EmitTypeFile("shared", sharedNs, null, en);
        }

        // ── Step 9: attribute definitions (NativeNameAttribute, NativeOffsetAttribute) ─

        sink.AddSource("Attributes", BuildAttributesSource(ns, schema));

        // ── Step 10: synthetics + handles + stubs ─────────────────────────────────

        sink.AddSource("Synthetics", SyntheticTypes.BuildSource(ns, reflectedNames, schema));

        // Handle value structs — CHandle<T>, CEntityHandle, CStrongHandle<T>,
        // CStrongHandleCopyable<T>, CStrongHandleVoid, CWeakHandle<T>. Always
        // emitted (no schema-dependent conditional) because every cs2 schema
        // we've seen references the typed handles, and emitting unconditionally
        // keeps the SDK contract stable across regens.
        sink.AddSource("Handles", HandleTypes.BuildSource(ns, schema));

        if (stubNames.Count > 0)
        {
            sink.AddSource("Stubs", BuildStubsSource(ns, stubNames, schema));
        }

        // ── Step 11: SchemaNames reverse-lookup table (F1) ────────────────────────

        sink.AddSource("SchemaNames", BuildSchemaNamesSource(ns, schema, sharedClasses, moduleClasses));

        // TM-2: surface every unknown atomic encountered during this emission so the
        // maintainer notices a new schema dumper type. Emitted as Info severity so
        // it never fails the build.
        foreach (string unknown in TypeMapper.GetUnresolvedAtomics()
                     .OrderBy(n => n, StringComparer.Ordinal))
        {
            sink.ReportDiagnostic(Descriptors.UnknownAtomicType, unknown);
        }

        // CS2_GEN_015: the subset of the above that upstream's own atomicCategory
        // calls a container. Ordered by field count so the largest offender leads
        // the list.
        foreach ((string bare, (string category, int count)) in
                 TypeMapper.GetAtomicCategoryDrift()
                     .OrderByDescending(kv => kv.Value.Count)
                     .ThenBy(kv => kv.Key, StringComparer.Ordinal)
                     .Select(kv => (kv.Key, kv.Value)))
        {
            sink.ReportDiagnostic(Descriptors.AtomicCategoryDrift, bare, category, count);
        }

        // The name diagnostics (CS2_GEN_006 / CS2_GEN_009) used to be drained
        // here and no longer are — see the end of the exporter's Program.cs.
        //
        // WordSplitter accumulates across the whole run, but this method is only
        // the first half of one: GameEventsEmitter runs after it, and the
        // game-event names are the flat KV1 ones (`userid`, `thrusmoke`) that the
        // splitter exists for in the first place. Draining here emptied the
        // bucket before a single one of them had been folded, so the entire
        // game-event vocabulary was unreportable. The drain belongs to the host,
        // which owns the full sequence.
    }

    private static void AddReferenced(Dictionary<string, string> names, string original)
    {
        string sanitized = NameHelpers.SanitizeName(original);
        if (!names.ContainsKey(sanitized))
        {
            names[sanitized] = original;
        }
    }

    // ── Bucket helper ────────────────────────────────────────────────────────────

    private static void AddToModule<T>(Dictionary<string, List<T>> dict, string module, T item)
    {
        if (!dict.TryGetValue(module, out List<T>? list))
        {
            dict[module] = list = [];
        }

        list.Add(item);
    }

    // ── Fingerprint helpers ──────────────────────────────────────────────────────

    private static bool AllClassesIdentical(List<ClassModel> list)
    {
        string fp = ClassFingerprint(list[0]);
        for (int i = 1; i < list.Count; i++)
        {
            if (ClassFingerprint(list[i]) != fp)
            {
                return false;
            }
        }

        return true;
    }

    private static bool AllEnumsIdentical(List<EnumModel> list)
    {
        string fp = EnumFingerprint(list[0]);
        for (int i = 1; i < list.Count; i++)
        {
            if (EnumFingerprint(list[i]) != fp)
            {
                return false;
            }
        }

        return true;
    }

    private static string BuildAttributesSource(string ns, SchemaRoot schema)
    {
        StringBuilder sb = new();
        AppendSdkHeader(sb, ns, "Attributes", schema);
        sb.AppendLine("#nullable enable");
        sb.AppendLine();
        sb.AppendLine($"namespace {ns};");
        sb.AppendLine();
        sb.AppendLine("/// <summary>");
        sb.AppendLine("///     Preserves the original C++ field, type, or enum-member name.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("[AttributeUsage(AttributeTargets.Property | AttributeTargets.Field |");
        sb.AppendLine("                AttributeTargets.Class | AttributeTargets.Struct | AttributeTargets.Enum)]");
        sb.AppendLine("public sealed class NativeNameAttribute : Attribute");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>Initializes a new instance with the given native name.</summary>");
        sb.AppendLine("    /// <param name=\"name\">The original C++ identifier.</param>");
        sb.AppendLine("    public NativeNameAttribute(string name) => Name = name;");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>The original C++ identifier as it appears in the schema.</summary>");
        sb.AppendLine("    public string Name { get; }");
        sb.AppendLine("}");
        sb.AppendLine();
        sb.AppendLine("/// <summary>");
        sb.AppendLine("///     Records the byte offset of a property within its native C++ type.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("[AttributeUsage(AttributeTargets.Property)]");
        sb.AppendLine("public sealed class NativeOffsetAttribute : Attribute");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>Initializes a new instance with the given byte offset.</summary>");
        sb.AppendLine("    /// <param name=\"offset\">Byte offset from the start of the native type.</param>");
        sb.AppendLine("    public NativeOffsetAttribute(int offset) => Offset = offset;");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>Byte offset of this field from the start of the native object.</summary>");
        sb.AppendLine("    public int Offset { get; }");
        sb.AppendLine("}");
        sb.AppendLine();
        sb.AppendLine("/// <summary>");
        sb.AppendLine("///     Informational size in bytes of the native C++ type. Not a marshalling");
        sb.AppendLine("///     contract — the managed projection is not P/Invoke-compatible.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("[AttributeUsage(AttributeTargets.Class | AttributeTargets.Struct)]");
        sb.AppendLine("public sealed class NativeSizeAttribute : Attribute");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>Initializes a new instance with the given native size.</summary>");
        sb.AppendLine("    /// <param name=\"size\">Size of the native type in bytes.</param>");
        sb.AppendLine("    public NativeSizeAttribute(int size) => Size = size;");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>Size of the native type in bytes.</summary>");
        sb.AppendLine("    public int Size { get; }");
        sb.AppendLine("}");
        sb.AppendLine();
        sb.AppendLine("/// <summary>");
        sb.AppendLine("///     Round-trips a schema metadata marker (e.g. <c>MNotSaved</c>, <c>MNetworkVar</c>)");
        sb.AppendLine("///     from the native dump. Multiple markers per member are common.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("[AttributeUsage(AttributeTargets.Property | AttributeTargets.Field |");
        sb.AppendLine("                AttributeTargets.Class | AttributeTargets.Struct | AttributeTargets.Enum,");
        sb.AppendLine("                AllowMultiple = true)]");
        sb.AppendLine("public sealed class NativeMetadataAttribute : Attribute");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>Initializes a marker-only metadata entry.</summary>");
        sb.AppendLine("    public NativeMetadataAttribute(string name)");
        sb.AppendLine("    {");
        sb.AppendLine("        Name = name;");
        sb.AppendLine("        Value = null;");
        sb.AppendLine("    }");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>Initializes a metadata entry with a name and an associated value.</summary>");
        sb.AppendLine("    public NativeMetadataAttribute(string name, string value)");
        sb.AppendLine("    {");
        sb.AppendLine("        Name = name;");
        sb.AppendLine("        Value = value;");
        sb.AppendLine("    }");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>Marker name as it appears in the native schema (e.g. <c>MNotSaved</c>).</summary>");
        sb.AppendLine("    public string Name { get; }");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>Optional value associated with the marker, or null if marker-only.</summary>");
        sb.AppendLine("    public string? Value { get; }");
        sb.AppendLine("}");
        sb.AppendLine();
        // Both doc lines below name `sdk.supplement` alongside the three real
        // files. It is not a `.gameevents` basename and never was — it marks a
        // record carried in `game-event-supplement.json` because the extractor
        // cannot see the event at all. A consumer switching on this value has to
        // know that fourth case exists, and the enumeration is the only place
        // that tells them.
        sb.AppendLine("/// <summary>");
        sb.AppendLine("///     Records where an event record came from: the originating <c>.gameevents</c> file");
        sb.AppendLine("///     basename (<c>core.gameevents</c>, <c>game.gameevents</c>, <c>mod.gameevents</c>), or");
        sb.AppendLine("///     <c>sdk.supplement</c> for a curated event the extracted schema does not declare.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("[AttributeUsage(AttributeTargets.Class)]");
        sb.AppendLine("public sealed class GameEventSourceAttribute : Attribute");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>Initializes a new instance with the given source.</summary>");
        sb.AppendLine("    public GameEventSourceAttribute(string source) => Source = source;");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>");
        sb.AppendLine("    ///     Basename of the <c>.gameevents</c> file the event was declared in, or");
        sb.AppendLine("    ///     <c>sdk.supplement</c> when the event is curated rather than extracted.");
        sb.AppendLine("    /// </summary>");
        sb.AppendLine("    public string Source { get; }");
        sb.AppendLine("}");
        sb.AppendLine();
        sb.AppendLine("/// <summary>");
        sb.AppendLine("///     Records the raw KV1 type tag of an event field (e.g. <c>player_controller_and_pawn</c>,");
        sb.AppendLine("///     <c>ehandle</c>, <c>uint64</c>). The C# property type is the SDK's projection of");
        sb.AppendLine("///     this tag; the tag itself is preserved so downstream demo parsers and dispatchers");
        sb.AppendLine("///     can recover the exact wire shape.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("[AttributeUsage(AttributeTargets.Property)]");
        sb.AppendLine("public sealed class GameEventFieldTypeAttribute : Attribute");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>Initializes a new instance with the given KV1 type tag.</summary>");
        sb.AppendLine("    public GameEventFieldTypeAttribute(string typeTag) => TypeTag = typeTag;");
        sb.AppendLine();
        sb.AppendLine("    /// <summary>Raw KV1 type tag as it appears in <c>gameevents_schema.json</c>.</summary>");
        sb.AppendLine("    public string TypeTag { get; }");
        sb.AppendLine("}");
        sb.AppendLine();
        sb.AppendLine("/// <summary>");
        sb.AppendLine("///     Marks an event whose <c>properties.local</c> flag is set — the event is");
        sb.AppendLine("///     server-only and never sent to clients.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("[AttributeUsage(AttributeTargets.Class)]");
        sb.AppendLine("public sealed class GameEventLocalAttribute : Attribute { }");
        sb.AppendLine();
        sb.AppendLine("/// <summary>");
        sb.AppendLine("///     Marks an event whose <c>properties.reliable</c> flag is set — the engine");
        sb.AppendLine("///     queues delivery and retransmits on packet loss rather than fire-and-forget.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("[AttributeUsage(AttributeTargets.Class)]");
        sb.AppendLine("public sealed class GameEventReliableAttribute : Attribute { }");
        return sb.ToString();
    }

    private static string BuildModuleSource(
        string relativePath,
        string namespaceName,
        List<ClassModel>? classes,
        List<EnumModel>? enums,
        string rootNs,
        Dictionary<string, HashSet<string>> nameToNs,
        SchemaRoot schema)
    {
        List<ClassModel> sortedClasses = classes != null ? [..classes] : [];
        List<EnumModel> sortedEnums = enums != null ? [..enums] : [];
        sortedClasses.Sort((a, b) => StringComparer.Ordinal.Compare(a.Name, b.Name));
        sortedEnums.Sort((a, b) => StringComparer.Ordinal.Compare(a.Name, b.Name));

        StringBuilder sb = new(64 * 1024);
        AppendSdkHeader(sb, rootNs, relativePath, schema);
        sb.AppendLine("#nullable enable");
        sb.AppendLine("#pragma warning disable CS8618 // non-nullable field not initialised");
        sb.AppendLine("#pragma warning disable CS8714 // nullable type as Dictionary key");
        sb.AppendLine("#pragma warning disable CS0108 // member hides inherited member (C++ field shadowing)");

        // Compute the minimal set of cross-namespace using directives:
        // collect every type name referenced in this file's classes, look up each
        // name's namespace, and only emit usings for those actually needed.
        //
        // ImplicitUsings on the SDK csproj covers System and System.Collections.Generic;
        // namespace nesting means the parent namespace (rootNs) is always reachable
        // from a child namespace, so we never need `using {rootNs};`. Both are skipped
        // here so the emitter output matches what the formatter produces.
        SortedSet<string> neededNs = new(StringComparer.Ordinal);

        Dictionary<string, string> fileRefs = new(StringComparer.Ordinal);
        foreach (ClassModel cls in sortedClasses)
        {
            CollectFromClass(cls, fileRefs);
        }

        foreach (string typeName in fileRefs.Keys)
        {
            if (!nameToNs.TryGetValue(typeName, out HashSet<string>? candidates))
            {
                continue;
            }

            // Prefer-self: if the file's own namespace contains a type by this name,
            // namespace nesting reaches it without a using directive. This catches
            // "genuine conflict" types whose same name lives in both Client and
            // Server (or wherever) — without this rule, the per-module loop's last
            // write would force a cross-module using onto every Client file.
            if (candidates.Contains(namespaceName))
            {
                continue;
            }

            // Root-namespace candidates are reachable via namespace nesting too, so
            // a using is unnecessary if rootNs is in the set — except synthetic
            // atoms like AABB_t can also have a per-module class shadowing them, in
            // which case we need the per-module using to bind to the real class
            // rather than fall back to the (possibly-not-emitted) synthetic.
            string? chosen = null;
            foreach (string candidate in candidates)
            {
                if (candidate == rootNs)
                {
                    continue;
                }

                if (chosen == null || StringComparer.Ordinal.Compare(candidate, chosen) < 0)
                {
                    chosen = candidate;
                }
            }

            if (chosen != null)
            {
                neededNs.Add(chosen);
            }
            // else: only candidate was rootNs → namespace nesting handles it.
        }

        if (neededNs.Count > 0)
        {
            sb.AppendLine();
            sb.AppendLine("#region");
            sb.AppendLine();
            foreach (string reqNs in neededNs)
            {
                sb.AppendLine($"using {reqNs};");
            }

            sb.AppendLine();
            sb.AppendLine("#endregion");
        }

        sb.AppendLine();
        sb.AppendLine($"namespace {namespaceName};");
        sb.AppendLine();

        foreach (ClassModel cls in sortedClasses)
        {
            ClassEmitter.Emit(sb, cls);
        }

        foreach (EnumModel en in sortedEnums)
        {
            EnumEmitter.Emit(sb, en);
        }

        return sb.ToString();
    }

    // F1: reverse-lookup table mapping the generated C# property name back to the
    // original C++ field name. Emits as `SchemaNames.{ClassName}.{PropName}` const
    // strings so consumers can switch on a C# member name and recover the raw
    // schema identifier without runtime reflection over [NativeName].
    //
    // Determinism: classes are sorted by their C# name (ordinal). Within a class,
    // field order follows the schema (matching ClassEmitter, which preserves
    // declaration order for offset-stable layout). Duplicate C# class names —
    // possible when two modules carry a "genuine conflict" same-name pair — are
    // resolved first-wins, with shared-bucket classes taking precedence over
    // per-module classes (so the canonical Common copy is the one consumers see).
    private static string BuildSchemaNamesSource(
        string ns,
        SchemaRoot schema,
        List<ClassModel> sharedClasses,
        Dictionary<string, List<ClassModel>> moduleClasses)
    {
        Dictionary<string, ClassModel> uniqueByCsName = new(StringComparer.Ordinal);

        void Consider(ClassModel cls)
        {
            string csName = TypeMapper.LookupCsName(cls.Name);
            if (!uniqueByCsName.ContainsKey(csName))
            {
                uniqueByCsName[csName] = cls;
            }
        }

        foreach (ClassModel cls in sharedClasses)
        {
            Consider(cls);
        }

        foreach (KeyValuePair<string, List<ClassModel>> kvp in moduleClasses
                     .OrderBy(kv => kv.Key, StringComparer.Ordinal))
        {
            foreach (ClassModel cls in kvp.Value)
            {
                Consider(cls);
            }
        }

        StringBuilder sb = new();
        AppendSdkHeader(sb, ns, "SchemaNames", schema);
        sb.AppendLine("#nullable enable");
        // CS1591: SchemaNames is a mechanical reverse-lookup with hundreds of
        // const-string entries; per-member XML doc would dwarf the actual data
        // without telling the reader anything useful. Suppress at file scope.
        sb.AppendLine("#pragma warning disable CS1591");
        sb.AppendLine();
        sb.AppendLine($"namespace {ns};");
        sb.AppendLine();
        sb.AppendLine("/// <summary>");
        sb.AppendLine("///     Reverse-lookup table from generated C# property names to the original");
        sb.AppendLine("///     C++ identifiers as they appear in <c>schemas.json</c>.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("public static class SchemaNames");
        sb.AppendLine("{");

        bool firstClass = true;
        foreach (KeyValuePair<string, ClassModel> kv in uniqueByCsName
                     .OrderBy(p => p.Key, StringComparer.Ordinal))
        {
            ClassModel cls = kv.Value;
            if (cls.Fields.Length == 0)
            {
                continue;
            }

            if (!firstClass)
            {
                sb.AppendLine();
            }

            firstClass = false;

            string classCsName = NameHelpers.Esc(kv.Key);
            sb.AppendLine($"    public static class {classCsName}");
            sb.AppendLine("    {");

            // Alphabetise consts by property name to match formatter convention.
            string[] propNames = ClassEmitter.ComputePropNames(cls.Fields, classCsName);
            int[] order = new int[cls.Fields.Length];
            for (int i = 0; i < cls.Fields.Length; i++)
            {
                order[i] = i;
            }

            Array.Sort(order, (a, b) => StringComparer.Ordinal.Compare(propNames[a], propNames[b]));

            foreach (int i in order)
            {
                string propName = propNames[i];
                string nativeName = NameHelpers.EscAttrString(cls.Fields[i].Name);
                sb.AppendLine($"        public const string {propName} = \"{nativeName}\";");
            }

            sb.AppendLine("    }");
        }

        sb.AppendLine("}");
        return sb.ToString();
    }

    private static string BuildStubsSource(string ns, SortedDictionary<string, string> names, SchemaRoot schema)
    {
        StringBuilder sb = new();
        AppendSdkHeader(sb, ns, "Stubs", schema);
        sb.AppendLine("// Types referenced in field declarations but not present in cs2_schema.json.");
        sb.AppendLine("// They live in tool modules that are not loaded during the dump, so we have no");
        sb.AppendLine("// fields / size / parents to project — the stub class exists purely so the");
        sb.AppendLine("// referencing property declaration compiles. Stubs are decorated with");
        sb.AppendLine("// `[EditorBrowsable(Never)]` so they don't pollute IntelliSense — consumers who");
        sb.AppendLine("// need to reference one explicitly can still do so by spelling the name.");
        sb.AppendLine();
        sb.AppendLine("#region");
        sb.AppendLine();
        sb.AppendLine("using System.ComponentModel;");
        sb.AppendLine();
        sb.AppendLine("#endregion");
        sb.AppendLine();
        sb.AppendLine($"namespace {ns};");
        sb.AppendLine();
        foreach (KeyValuePair<string, string> kv in names)
        {
            string sanitized = kv.Key;
            string original = kv.Value;
            // Escaped, because the stub names are raw C++ and a good many are
            // templates: `CAnimGraph2ParamOptionalRef< CGlobalSymbol >` puts a
            // bare `<` inside the summary and the compiler reads it as an
            // element, giving CS1570 "badly formed XML". The SDK csproj
            // generates a documentation file, so that is an error and not a
            // warning — 5,430 of them on the first 2.0 regen. Everywhere else
            // that interpolates a schema name into XML already escapes it.
            //
            // Two kinds of stub, and the summary says which: an undecided one is
            // an open item CS2_GEN_003 also reports; a deliberate one is a
            // recorded decision, so its summary points at the reasoning rather
            // than inviting a fix.
            string reason = TypeMapper.DeliberatelyStubbedAtoms.Contains(TypeMapper.BareAtomName(original))
                ? "deliberately unprojected; the list and the reasons are in TypeMapper.DeliberatelyStubbedAtoms"
                : "forward-declared stub (type not reflected in cs2_schema.json)";
            sb.AppendLine($"/// <summary>{NameHelpers.XmlEscape(original)} — {reason}.</summary>");
            // CE-1: when SanitizeName had to rewrite the original (typically because
            // it contained C++ scope operators), preserve the original via [NativeName]
            // so runtime interop can round-trip back to the schema identifier.
            if (sanitized != original)
            {
                sb.AppendLine($"[NativeName(\"{original}\")]");
            }

            sb.AppendLine("[EditorBrowsable(EditorBrowsableState.Never)]");
            sb.AppendLine($"public partial class {NameHelpers.Esc(sanitized)}");
            sb.AppendLine("{");
            sb.AppendLine("}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    // Parent names (in order) + field names (in order).
    // Offsets/types intentionally excluded: they can differ across modules while
    // the logical structure (inheritance + field names) is the same.
    private static string ClassFingerprint(ClassModel cls)
    {
        StringBuilder sb = new();
        foreach (ParentModel p in cls.Parents)
        {
            sb.Append(p.Name);
            sb.Append(';');
        }

        sb.Append('|');
        foreach (FieldModel f in cls.Fields)
        {
            sb.Append(f.Name);
            sb.Append(';');
        }

        return sb.ToString();
    }

    // ── Conflict-propagation helpers ─────────────────────────────────────────────

    private static bool ClassReferencesAmbiguous(ClassModel cls, HashSet<string> ambiguous)
    {
        foreach (ParentModel p in cls.Parents)
        {
            if (ambiguous.Contains(NameHelpers.SanitizeName(p.Name)))
            {
                return true;
            }
        }

        foreach (FieldModel f in cls.Fields)
        {
            if (TypeReferencesAmbiguous(f.Type, ambiguous))
            {
                return true;
            }
        }

        return false;
    }

    // ── Referenced name collectors ───────────────────────────────────────────────

    // Walks a class's parents and field types, recording every external type name
    // referenced. The dictionary maps the sanitized C# identifier (used for stub
    // emission and dedup) back to the original C++ name from the schema (used by
    // CE-1 to emit [NativeName] on stubs whose sanitized form differs).
    //
    // First-original-wins on collision: in the rare case two distinct C++ names
    // sanitize to the same identifier, the first-encountered original is preserved.
    private static void CollectFromClass(ClassModel cls, Dictionary<string, string> names)
    {
        // Only the first parent appears in the inheritance clause; additional parents
        // are emitted into a `// Additional parents: …` comment by ClassEmitter, so
        // their names don't need usings. Walking past index 0 would over-collect (and
        // the formatter would strip the resulting using on every pass).
        if (cls.Parents.Length > 0)
        {
            AddReferenced(names, cls.Parents[0].Name);
        }

        foreach (FieldModel f in cls.Fields)
        {
            CollectReferencedNames(f.Type, names);
        }
    }

    private static void CollectReferencedNames(TypeModel type, Dictionary<string, string> names)
    {
        switch (type)
        {
            case DeclaredClassType dc:
                AddReferenced(names, dc.Name);
                break;
            case DeclaredEnumType de:
                AddReferenced(names, de.Name);
                break;
            case PtrType pt:
                CollectReferencedNames(pt.Inner, names);
                break;
            case FixedArrayType fa:
                CollectReferencedNames(fa.Inner, names);
                break;
            case AtomicType at:
                // Q3: an atomic whose name isn't in any TypeMapper classification set
                // (and isn't a HandleKind variant) will be projected as a stub class.
                // Add its sanitized name so the stub-collection step picks it up.
                if (at.HandleKind == null && !TypeMapper.IsKnownAtomicName(at.Name))
                {
                    AddReferenced(names, at.Name);
                }

                // Only recurse into Inner/Inner2 when the atomic's C# projection
                // actually surfaces them. `CResourceNameTyped<MDLName_t>` projects
                // to plain `string`, so `MDLName_t` never appears in the emitted
                // source and must not contribute to the file's `using` set.
                if (at.Inner != null && TypeMapper.AtomicProjectionUsesInner(at.Name, at.HandleKind))
                {
                    CollectReferencedNames(at.Inner, names);
                }

                if (at.Inner2 != null && TypeMapper.AtomicProjectionUsesInner2(at.Name))
                {
                    CollectReferencedNames(at.Inner2, names);
                }

                break;
        }
    }

    private static string EnumFingerprint(EnumModel en)
    {
        StringBuilder sb = new();
        foreach (MemberModel m in en.Members)
        {
            sb.Append(m.Name);
            sb.Append(':');
            sb.Append(m.Value);
            sb.Append(';');
        }

        return sb.ToString();
    }

    // ── Namespace helper ─────────────────────────────────────────────────────────

    // Converts a module name to a PascalCase namespace segment.
    // Splits on underscores so compound names become proper PascalCase:
    //   "client"             → "Client"
    //   "animationsystem"    → "Animationsystem"
    //   "panorama_content"   → "PanoramaContent"
    //   "pulse_runtime_lib"  → "PulseRuntimeLib"
    //   "soundsystem_lowlevel" → "SoundsystemLowlevel"
    private static string ToNamespacePart(string module)
    {
        // "shared" → "Common": avoids the CA1716 conflict with the VB.NET keyword "Shared"
        if (module == "shared")
        {
            return "Common";
        }

        StringBuilder sb = new();
        foreach (string segment in module.Split('_'))
        {
            // Everything that is not legal in a C# identifier is dropped rather
            // than passed through. Every module name in schema 1.x is
            // [a-z0-9_]+, so this changes nothing today — but schema 2.0 module
            // names are binaries, and one of them is `!GlobalTypes`, which fell
            // through verbatim and emitted `namespace CS2OpenSchema.!GlobalTypes;`
            // across 591 files. That is a syntax error, not a bad name: the
            // package would not have compiled at all.
            bool first = true;
            foreach (char c in segment)
            {
                if (!char.IsLetterOrDigit(c) && c != '_')
                {
                    continue;
                }

                sb.Append(first ? char.ToUpperInvariant(c) : c);
                first = false;
            }
        }

        if (sb.Length == 0)
        {
            return "Unknown";
        }

        // A namespace part cannot open with a digit. Reachable only if a module
        // name ever starts with one; cheap to rule out.
        return char.IsDigit(sb[0]) ? "_" + sb : sb.ToString();
    }

    private static bool TypeReferencesAmbiguous(TypeModel type, HashSet<string> ambiguous)
    {
        return type switch
        {
            DeclaredClassType dc => ambiguous.Contains(NameHelpers.SanitizeName(dc.Name)),
            DeclaredEnumType de => ambiguous.Contains(NameHelpers.SanitizeName(de.Name)),
            PtrType pt => TypeReferencesAmbiguous(pt.Inner, ambiguous),
            FixedArrayType fa => TypeReferencesAmbiguous(fa.Inner, ambiguous),
            AtomicType at => at.Inner != null && TypeReferencesAmbiguous(at.Inner, ambiguous) ||
                             at.Inner2 != null && TypeReferencesAmbiguous(at.Inner2, ambiguous),
            _ => false
        };
    }
}
